package ageimpl

import (
	"crypto/ecdsa"
	"crypto/ed25519"
	"crypto/rand"
	"crypto/rsa"
	"crypto/sha256"
	"crypto/sha512"
	"errors"
	"fmt"
	"math/big"
	"strings"

	"golang.org/x/crypto/ssh"
)

const (
	recipientHRP = "age"
	identityHRP  = "age-secret-key-"
)

var (
	curve25519P = new(big.Int).Sub(new(big.Int).Lsh(big.NewInt(1), 255), big.NewInt(19))
	basepoint   = []byte{9}
)

type X25519Recipient struct {
	Public [32]byte
}

type X25519Identity struct {
	Secret [32]byte
	Public [32]byte
}

func NewX25519Identity(secret []byte) (*X25519Identity, error) {
	if len(secret) != 32 {
		return nil, errors.New("invalid X25519 secret key length")
	}
	var ident X25519Identity
	copy(ident.Secret[:], secret)
	pub, err := x25519ScalarMult(ident.Secret[:], basepoint)
	if err != nil {
		return nil, err
	}
	copy(ident.Public[:], pub)
	return &ident, nil
}

func GenerateX25519Identity() (*X25519Identity, error) {
	var secret [32]byte
	if _, err := rand.Read(secret[:]); err != nil {
		return nil, err
	}
	secret[0] &= 248
	secret[31] &= 127
	secret[31] |= 64
	return NewX25519Identity(secret[:])
}

func ParseRecipient(s string) (*X25519Recipient, error) {
	hrp, payload, err := bech32Decode(strings.TrimSpace(s))
	if err != nil {
		return nil, err
	}
	if hrp != recipientHRP || len(payload) != 32 {
		return nil, errors.New("invalid recipient")
	}
	var r X25519Recipient
	copy(r.Public[:], payload)
	return &r, nil
}

func ParseIdentity(s string) (*X25519Identity, error) {
	hrp, payload, err := bech32Decode(strings.TrimSpace(s))
	if err != nil {
		return nil, err
	}
	if hrp != identityHRP || len(payload) != 32 {
		return nil, errors.New("invalid identity")
	}
	return NewX25519Identity(payload)
}

func (r *X25519Recipient) String() string {
	s, _ := bech32Encode(recipientHRP, r.Public[:], false)
	return s
}

func (i *X25519Identity) String() string {
	s, _ := bech32Encode(identityHRP, i.Secret[:], true)
	return s
}

type SSHRecipient interface {
	sshRecipientTag() string
}

type SSHEd25519Recipient struct {
	Public ed25519.PublicKey
}

type SSHEd25519Identity struct {
	Private ed25519.PrivateKey
	Public  ed25519.PublicKey
}

type SSHRSARecipient struct {
	Public *rsa.PublicKey
	Blob   []byte
}

type SSHRSAIdentity struct {
	Private *rsa.PrivateKey
	Blob    []byte
}

func ParseAuthorizedRecipient(line string) (Recipient, error) {
	pub, _, _, _, err := ssh.ParseAuthorizedKey([]byte(strings.TrimSpace(line)))
	if err != nil {
		return nil, fmt.Errorf("unknown recipient type: %q", line)
	}
	return recipientFromSSHPublic(pub)
}

func recipientFromSSHPublic(pub ssh.PublicKey) (Recipient, error) {
	switch pk := pub.(type) {
	case ssh.CryptoPublicKey:
		switch key := pk.CryptoPublicKey().(type) {
		case ed25519.PublicKey:
			return &SSHEd25519Recipient{Public: key}, nil
		case *rsa.PublicKey:
			if key.N.BitLen() < 2048 {
				return nil, fmt.Errorf("unsupported SSH key of type %q", pub.Type())
			}
			return &SSHRSARecipient{Public: key, Blob: pub.Marshal()}, nil
		case *ecdsa.PublicKey:
			return nil, fmt.Errorf("unsupported SSH key of type %q", pub.Type())
		default:
			return nil, fmt.Errorf("unsupported SSH key of type %q", pub.Type())
		}
	default:
		return nil, fmt.Errorf("unsupported SSH key of type %q", pub.Type())
	}
}

func ParseSSHIdentity(data []byte) (Identity, error) {
	key, err := ssh.ParseRawPrivateKey(data)
	if err != nil {
		return nil, err
	}
	switch k := key.(type) {
	case ed25519.PrivateKey:
		pub := k.Public().(ed25519.PublicKey)
		return &SSHEd25519Identity{Private: k, Public: pub}, nil
	case *rsa.PrivateKey:
		pub, err := ssh.NewPublicKey(&k.PublicKey)
		if err != nil {
			return nil, err
		}
		return &SSHRSAIdentity{Private: k, Blob: pub.Marshal()}, nil
	default:
		return nil, errors.New("unknown identity type")
	}
}

func (r *SSHEd25519Recipient) tag() string {
	sum := sha256.Sum256(sshBlobForEd25519(r.Public))
	return rawBase64(sum[:4])
}

func (r *SSHEd25519Recipient) sshRecipientTag() string { return r.tag() }

func (r *SSHRSARecipient) tag() string {
	sum := sha256.Sum256(r.Blob)
	return rawBase64(sum[:4])
}

func (r *SSHRSARecipient) sshRecipientTag() string { return r.tag() }

func sshBlobForEd25519(pub ed25519.PublicKey) []byte {
	sshPub, _ := ssh.NewPublicKey(pub)
	return sshPub.Marshal()
}

func ed25519PublicToX25519(pub ed25519.PublicKey) ([32]byte, error) {
	var out [32]byte
	if len(pub) != ed25519.PublicKeySize {
		return out, errors.New("invalid Ed25519 public key")
	}
	yBytes := append([]byte(nil), pub...)
	yBytes[31] &= 0x7f
	// Interpret the encoded y-coordinate as little-endian.
	y := new(big.Int)
	for i := len(yBytes) - 1; i >= 0; i-- {
		y.Lsh(y, 8)
		y.Or(y, new(big.Int).SetUint64(uint64(yBytes[i])))
	}

	one := big.NewInt(1)
	num := new(big.Int).Add(one, y)
	num.Mod(num, curve25519P)
	den := new(big.Int).Sub(one, y)
	den.Mod(den, curve25519P)
	if den.Sign() == 0 {
		return out, errors.New("invalid Ed25519 public key")
	}
	denInv := new(big.Int).ModInverse(den, curve25519P)
	if denInv == nil {
		return out, errors.New("invalid Ed25519 public key")
	}
	u := new(big.Int).Mul(num, denInv)
	u.Mod(u, curve25519P)

	ub := u.FillBytes(make([]byte, 32))
	for i := 0; i < 16; i++ {
		ub[i], ub[31-i] = ub[31-i], ub[i]
	}
	copy(out[:], ub)
	return out, nil
}

func ed25519PrivateToX25519(priv ed25519.PrivateKey) ([32]byte, error) {
	var out [32]byte
	if len(priv) != ed25519.PrivateKeySize {
		return out, errors.New("invalid Ed25519 private key")
	}
	sum := sha512.Sum512(priv.Seed())
	copy(out[:], sum[:32])
	out[0] &= 248
	out[31] &= 127
	out[31] |= 64
	return out, nil
}

