package ageimpl

import (
	"errors"
	"strings"
)

const bech32Charset = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"

var bech32DecodeMap [128]byte

func init() {
	for i := range bech32DecodeMap {
		bech32DecodeMap[i] = 0xff
	}
	for i := 0; i < len(bech32Charset); i++ {
		bech32DecodeMap[bech32Charset[i]] = byte(i)
	}
}

func bech32Encode(hrp string, data []byte, upper bool) (string, error) {
	values, err := convertBits(data, 8, 5, true)
	if err != nil {
		return "", err
	}
	checksum := bech32Checksum(hrp, values)
	combined := append(append([]byte{}, values...), checksum...)

	var b strings.Builder
	if upper {
		b.Grow(len(hrp) + 1 + len(combined))
		b.WriteString(strings.ToUpper(hrp))
		b.WriteByte('1')
		for _, v := range combined {
			b.WriteByte(byte(strings.ToUpper(string(bech32Charset[v]))[0]))
		}
		return b.String(), nil
	}

	b.Grow(len(hrp) + 1 + len(combined))
	b.WriteString(strings.ToLower(hrp))
	b.WriteByte('1')
	for _, v := range combined {
		b.WriteByte(bech32Charset[v])
	}
	return b.String(), nil
}

func bech32Decode(s string) (string, []byte, error) {
	if len(s) < 8 {
		return "", nil, errors.New("invalid bech32 string")
	}
	lower := strings.ToLower(s)
	upper := strings.ToUpper(s)
	if s != lower && s != upper {
		return "", nil, errors.New("mixed-case bech32 string")
	}
	s = lower
	pos := strings.LastIndexByte(s, '1')
	if pos < 1 || pos+7 > len(s) {
		return "", nil, errors.New("invalid bech32 separator")
	}
	hrp := s[:pos]
	raw := s[pos+1:]
	values := make([]byte, len(raw))
	for i := range raw {
		c := raw[i]
		if c >= byte(len(bech32DecodeMap)) || bech32DecodeMap[c] == 0xff {
			return "", nil, errors.New("invalid bech32 character")
		}
		values[i] = bech32DecodeMap[c]
	}
	if !bech32VerifyChecksum(hrp, values) {
		return "", nil, errors.New("invalid bech32 checksum")
	}
	payload, err := convertBits(values[:len(values)-6], 5, 8, false)
	if err != nil {
		return "", nil, err
	}
	return hrp, payload, nil
}

func convertBits(data []byte, fromBits, toBits uint, pad bool) ([]byte, error) {
	var acc, bits uint
	maxv := uint((1 << toBits) - 1)
	maxAcc := uint((1 << (fromBits + toBits - 1)) - 1)
	out := make([]byte, 0, len(data)*int(fromBits)/int(toBits)+1)
	for _, v := range data {
		if uint(v)>>fromBits != 0 {
			return nil, errors.New("invalid data range")
		}
		acc = ((acc << fromBits) | uint(v)) & maxAcc
		bits += fromBits
		for bits >= toBits {
			bits -= toBits
			out = append(out, byte((acc>>bits)&maxv))
		}
	}
	if pad {
		if bits > 0 {
			out = append(out, byte((acc<<(toBits-bits))&maxv))
		}
	} else if bits >= fromBits || ((acc<<(toBits-bits))&maxv) != 0 {
		return nil, errors.New("invalid padding")
	}
	return out, nil
}

func bech32Checksum(hrp string, data []byte) []byte {
	values := append(bech32HrpExpand(hrp), data...)
	values = append(values, 0, 0, 0, 0, 0, 0)
	mod := bech32Polymod(values) ^ 1
	out := make([]byte, 6)
	for i := 0; i < 6; i++ {
		out[i] = byte((mod >> uint(5*(5-i))) & 31)
	}
	return out
}

func bech32VerifyChecksum(hrp string, data []byte) bool {
	values := append(bech32HrpExpand(hrp), data...)
	return bech32Polymod(values) == 1
}

func bech32HrpExpand(hrp string) []byte {
	out := make([]byte, 0, len(hrp)*2+1)
	for i := range hrp {
		out = append(out, hrp[i]>>5)
	}
	out = append(out, 0)
	for i := range hrp {
		out = append(out, hrp[i]&31)
	}
	return out
}

func bech32Polymod(values []byte) uint32 {
	gens := [5]uint32{0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3}
	chk := uint32(1)
	for _, v := range values {
		top := chk >> 25
		chk = (chk&0x1ffffff)<<5 ^ uint32(v)
		for i, gen := range gens {
			if (top>>uint(i))&1 == 1 {
				chk ^= gen
			}
		}
	}
	return chk
}

