package ageimpl

import "fmt"

type Stanza struct {
	Type string
	Args []string
	Body []byte
}

type Recipient interface {
	Wrap(fileKey []byte) (*Stanza, error)
}

type Identity interface {
	Unwrap(stanza *Stanza) ([]byte, error)
	Recipient() (Recipient, error)
}

type PluginRecipient struct {
	Name string
}

type PluginIdentity struct {
	Name string
}

func (p *PluginRecipient) Wrap(_ []byte) (*Stanza, error) {
	return nil, fmt.Errorf("failed to wrap key for recipient #0: %s plugin: couldn't start plugin: %q plugin not found: exec: %q: executable file not found in $PATH", p.Name, p.Name, "age-plugin-"+p.Name)
}

func (p *PluginIdentity) Unwrap(_ *Stanza) ([]byte, error) {
	return nil, fmt.Errorf("%s plugin: couldn't start plugin: %q plugin not found: exec: %q: executable file not found in $PATH", p.Name, p.Name, "age-plugin-"+p.Name)
}

func (p *PluginIdentity) Recipient() (Recipient, error) {
	return &PluginRecipient{Name: p.Name}, nil
}

