package ageimpl

import (
	"bytes"
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"errors"
	"fmt"
	"io"
	"strings"

	"crypto/hkdf"

	"golang.org/x/crypto/chacha20poly1305"
	"golang.org/x/crypto/scrypt"
)

const (
	headerIntro   = "age-encryption.org/v1"
	armorBegin    = "-----BEGIN AGE ENCRYPTED FILE-----"
	armorEnd      = "-----END AGE ENCRYPTED FILE-----"
	chunkSize     = 64 * 1024
	headerMacSize = 32
	fileKeySize   = 16
)

var (
	ErrIncorrectIdentity   = errors.New("incorrect identity")
	ErrIncorrectPassphrase = errors.New("incorrect passphrase")
	ErrInvalidHeaderMAC    = errors.New("invalid header MAC")
)

type ParsedFile struct {
	Armored      bool
	Header       []*Stanza
	HeaderPrefix []byte
	HeaderMAC    []byte
	Payload      []byte
}

func Encrypt(plaintext []byte, recipients []Recipient) ([]byte, error) {
	fileKey := make([]byte, fileKeySize)
	if _, err := rand.Read(fileKey); err != nil {
		return nil, err
	}
	stanzas := make([]*Stanza, 0, len(recipients))
	for _, r := range recipients {
		stanza, err := r.Wrap(fileKey)
		if err != nil {
			return nil, err
		}
		stanzas = append(stanzas, stanza)
	}
	header, err := marshalHeader(fileKey, stanzas)
	if err != nil {
		return nil, err
	}
	payload, err := encryptPayload(fileKey, plaintext)
	if err != nil {
		return nil, err
	}
	return append(header, payload...), nil
}

func EncryptWithPassphrase(plaintext []byte, passphrase string, workFactor int) ([]byte, error) {
	fileKey := make([]byte, fileKeySize)
	if _, err := rand.Read(fileKey); err != nil {
		return nil, err
	}
	salt := make([]byte, 16)
	if _, err := rand.Read(salt); err != nil {
		return nil, err
	}
	key, err := scryptKey(passphrase, salt, workFactor)
	if err != nil {
		return nil, err
	}
	stanza := &Stanza{
		Type: "scrypt",
		Args: []string{rawBase64(salt), fmt.Sprintf("%d", workFactor)},
	}
	body, err := wrapFileKey(key, stanzaAAD(stanza.Type, stanza.Args), fileKey)
	if err != nil {
		return nil, err
	}
	stanza.Body = body
	header, err := marshalHeader(fileKey, []*Stanza{stanza})
	if err != nil {
		return nil, err
	}
	payload, err := encryptPayload(fileKey, plaintext)
	if err != nil {
		return nil, err
	}
	return append(header, payload...), nil
}

func ParseCiphertext(data []byte) (*ParsedFile, error) {
	decoded, armored, err := maybeDecodeArmor(data)
	if err != nil {
		return nil, err
	}
	lines := bytes.Split(decoded, []byte{'\n'})
	if len(lines) < 4 {
		return nil, errors.New("failed to read header: parsing age header: malformed header")
	}
	if string(lines[0]) != headerIntro {
		return nil, fmt.Errorf("failed to read header: parsing age header: unexpected intro: %q", string(lines[0])+"\n")
	}
	prefix := append([]byte{}, lines[0]...)
	prefix = append(prefix, '\n')
	var stanzas []*Stanza
	var current *Stanza
	offset := len(prefix)
	rest := decoded[offset:]
	reader := bytes.NewBuffer(rest)
	for {
		line, err := reader.ReadBytes('\n')
		if err != nil {
			return nil, errors.New("failed to read header: parsing age header: missing header MAC")
		}
		offset += len(line)
		if bytes.HasPrefix(line, []byte("--- ")) {
			mac, err := base64.RawStdEncoding.DecodeString(strings.TrimSpace(string(line[4:])))
			if err != nil || len(mac) != headerMacSize {
				return nil, errors.New("failed to read header: parsing age header: malformed header MAC")
			}
			return &ParsedFile{
				Armored:      armored,
				Header:       stanzas,
				HeaderPrefix: decoded[:offset-len(line)],
				HeaderMAC:    mac,
				Payload:      decoded[offset:],
			}, nil
		}
		if bytes.HasPrefix(line, []byte("-> ")) {
			fields := strings.Fields(strings.TrimSpace(string(line[3:])))
			if len(fields) == 0 {
				return nil, errors.New("failed to read header: parsing age header: malformed recipient stanza")
			}
			current = &Stanza{Type: fields[0], Args: append([]string{}, fields[1:]...)}
			stanzas = append(stanzas, current)
			continue
		}
		if current == nil {
			return nil, errors.New("failed to read header: parsing age header: malformed recipient stanza")
		}
		bodyPart := strings.TrimSpace(string(line))
		decodedLine, err := base64.RawStdEncoding.DecodeString(bodyPart)
		if err != nil {
			return nil, errors.New("failed to read header: parsing age header: malformed recipient body")
		}
		current.Body = append(current.Body, decodedLine...)
	}
}

func DecryptWithIdentities(parsed *ParsedFile, identities []Identity) ([]byte, error) {
	for _, id := range identities {
		for _, stanza := range parsed.Header {
			fileKey, err := id.Unwrap(stanza)
			if err != nil {
				continue
			}
			if err := verifyHeaderMAC(fileKey, parsed.HeaderPrefix, parsed.HeaderMAC); err != nil {
				continue
			}
			return decryptPayload(fileKey, parsed.Payload)
		}
	}
	return nil, ErrIncorrectIdentity
}

func DecryptWithPassphrase(parsed *ParsedFile, passphrase string) ([]byte, error) {
	for _, stanza := range parsed.Header {
		if stanza.Type != "scrypt" || len(stanza.Args) != 2 {
			continue
		}
		salt, err := base64.RawStdEncoding.DecodeString(stanza.Args[0])
		if err != nil {
			continue
		}
		workFactor, err := parseInt(stanza.Args[1])
		if err != nil {
			continue
		}
		key, err := scryptKey(passphrase, salt, workFactor)
		if err != nil {
			return nil, err
		}
		fileKey, err := unwrapFileKey(key, stanzaAAD(stanza.Type, stanza.Args), stanza.Body)
		if err != nil {
			continue
		}
		if err := verifyHeaderMAC(fileKey, parsed.HeaderPrefix, parsed.HeaderMAC); err != nil {
			continue
		}
		return decryptPayload(fileKey, parsed.Payload)
	}
	return nil, ErrIncorrectPassphrase
}

func IsPassphraseFile(parsed *ParsedFile) bool {
	for _, stanza := range parsed.Header {
		if stanza.Type == "scrypt" {
			return true
		}
	}
	return false
}

func Armor(data []byte) []byte {
	enc := base64.StdEncoding.EncodeToString(data)
	var b strings.Builder
	b.Grow(len(armorBegin) + len(armorEnd) + len(enc) + len(enc)/64 + 3)
	b.WriteString(armorBegin)
	b.WriteByte('\n')
	for len(enc) > 64 {
		b.WriteString(enc[:64])
		b.WriteByte('\n')
		enc = enc[64:]
	}
	if len(enc) > 0 {
		b.WriteString(enc)
		b.WriteByte('\n')
	}
	b.WriteString(armorEnd)
	b.WriteByte('\n')
	return []byte(b.String())
}

func maybeDecodeArmor(data []byte) ([]byte, bool, error) {
	if !bytes.HasPrefix(data, []byte(armorBegin)) {
		return data, false, nil
	}
	text := strings.ReplaceAll(string(data), "\r\n", "\n")
	lines := strings.Split(text, "\n")
	if len(lines) < 3 || lines[0] != armorBegin {
		return nil, true, errors.New("failed to read header: parsing age header: malformed armor")
	}
	var body strings.Builder
	foundEnd := false
	for i := 1; i < len(lines); i++ {
		if lines[i] == armorEnd {
			foundEnd = true
			for j := i + 1; j < len(lines); j++ {
				if strings.TrimSpace(lines[j]) != "" {
					return nil, true, errors.New("failed to read header: parsing age header: malformed armor")
				}
			}
			break
		}
		if lines[i] == "" {
			continue
		}
		body.WriteString(lines[i])
	}
	if !foundEnd {
		return nil, true, errors.New("failed to read header: parsing age header: malformed armor")
	}
	decoded, err := base64.StdEncoding.DecodeString(body.String())
	if err != nil {
		return nil, true, errors.New("failed to read header: parsing age header: malformed armor")
	}
	return decoded, true, nil
}

func marshalHeader(fileKey []byte, stanzas []*Stanza) ([]byte, error) {
	var b bytes.Buffer
	b.WriteString(headerIntro)
	b.WriteByte('\n')
	for _, stanza := range stanzas {
		b.Write(stanzaAAD(stanza.Type, stanza.Args))
		body := rawBase64(stanza.Body)
		for len(body) > 64 {
			b.WriteString(body[:64])
			b.WriteByte('\n')
			body = body[64:]
		}
		b.WriteString(body)
		b.WriteByte('\n')
	}
	mac := computeHeaderMAC(fileKey, b.Bytes())
	b.WriteString("--- ")
	b.WriteString(rawBase64(mac))
	b.WriteByte('\n')
	return b.Bytes(), nil
}

func stanzaAAD(typ string, args []string) []byte {
	var b strings.Builder
	b.WriteString("-> ")
	b.WriteString(typ)
	for _, arg := range args {
		b.WriteByte(' ')
		b.WriteString(arg)
	}
	b.WriteByte('\n')
	return []byte(b.String())
}

func wrapFileKey(key, aad, fileKey []byte) ([]byte, error) {
	aead, err := chacha20poly1305.New(key)
	if err != nil {
		return nil, err
	}
	return aead.Seal(nil, make([]byte, chacha20poly1305.NonceSize), fileKey, aad), nil
}

func unwrapFileKey(key, aad, body []byte) ([]byte, error) {
	aead, err := chacha20poly1305.New(key)
	if err != nil {
		return nil, err
	}
	return aead.Open(nil, make([]byte, chacha20poly1305.NonceSize), body, aad)
}

func computeHeaderMAC(fileKey, header []byte) []byte {
	key := hkdfExpand(fileKey, nil, []byte("header"), 32)
	h := hmac.New(sha256.New, key)
	h.Write(header)
	return h.Sum(nil)
}

func verifyHeaderMAC(fileKey, header, mac []byte) error {
	expected := computeHeaderMAC(fileKey, header)
	if !hmac.Equal(expected, mac) {
		return ErrInvalidHeaderMAC
	}
	return nil
}

func hkdfExpand(secret, salt, info []byte, size int) []byte {
	reader := hkdf.New(sha256.New, secret, salt, info)
	out := make([]byte, size)
	io.ReadFull(reader, out)
	return out
}

func scryptKey(passphrase string, salt []byte, workFactor int) ([]byte, error) {
	if workFactor < 1 || workFactor > 30 {
		return nil, errors.New("invalid scrypt work factor")
	}
	combinedSalt := append([]byte("age-encryption.org/v1/scrypt"), salt...)
	return scrypt.Key([]byte(passphrase), combinedSalt, 1<<workFactor, 8, 1, 32)
}

func rawBase64(data []byte) string {
	return base64.RawStdEncoding.EncodeToString(data)
}

