package ageimpl

import (
	"crypto/rand"
	"encoding/binary"
	"errors"

	"golang.org/x/crypto/chacha20poly1305"
)

func encryptPayload(fileKey, plaintext []byte) ([]byte, error) {
	key := hkdfExpand(fileKey, nil, []byte("payload"), chacha20poly1305.KeySize)
	aead, err := chacha20poly1305.NewX(key)
	if err != nil {
		return nil, err
	}
	prefix := make([]byte, 16)
	if _, err := rand.Read(prefix); err != nil {
		return nil, err
	}
	out := append([]byte{}, prefix...)
	if len(plaintext) == 0 {
		nonce := streamNonce(prefix, 0, true)
		return aead.Seal(out, nonce, nil, nil), nil
	}
	for offset, counter := 0, uint64(0); ; counter++ {
		end := offset + chunkSize
		last := false
		if end >= len(plaintext) {
			end = len(plaintext)
			last = true
		}
		nonce := streamNonce(prefix, counter, last)
		out = aead.Seal(out, nonce, plaintext[offset:end], nil)
		if last {
			return out, nil
		}
		offset = end
	}
}

func decryptPayload(fileKey, payload []byte) ([]byte, error) {
	if len(payload) < 16+16 {
		return nil, errors.New("failed to decrypt payload")
	}
	key := hkdfExpand(fileKey, nil, []byte("payload"), chacha20poly1305.KeySize)
	aead, err := chacha20poly1305.NewX(key)
	if err != nil {
		return nil, err
	}
	prefix := append([]byte{}, payload[:16]...)
	rest := payload[16:]
	var out []byte
	for counter := uint64(0); ; counter++ {
		last := len(rest) <= chunkSize+16
		if len(rest) < 16 {
			return nil, errors.New("failed to decrypt payload")
		}
		chunkLen := chunkSize + 16
		if last {
			chunkLen = len(rest)
		}
		nonce := streamNonce(prefix, counter, last)
		plain, err := aead.Open(nil, nonce, rest[:chunkLen], nil)
		if err != nil {
			return nil, errors.New("failed to decrypt payload")
		}
		out = append(out, plain...)
		rest = rest[chunkLen:]
		if last {
			if len(rest) != 0 {
				return nil, errors.New("failed to decrypt payload")
			}
			return out, nil
		}
	}
}

func streamNonce(prefix []byte, counter uint64, last bool) []byte {
	nonce := make([]byte, chacha20poly1305.NonceSizeX)
	copy(nonce, prefix)
	binary.BigEndian.PutUint64(nonce[16:], counter)
	if last {
		nonce[23] = 1
	} else {
		nonce[23] = 0
	}
	return nonce
}

