package ageimpl

import (
	"crypto/rand"
	"crypto/rsa"
	"crypto/sha256"
	"encoding/base64"
	"errors"
	"fmt"
)

func (r *X25519Recipient) Wrap(fileKey []byte) (*Stanza, error) {
	ephemeral, err := GenerateX25519Identity()
	if err != nil {
		return nil, err
	}
	shared, err := x25519ScalarMult(ephemeral.Secret[:], r.Public[:])
	if err != nil {
		return nil, err
	}
	salt := append(append([]byte{}, ephemeral.Public[:]...), r.Public[:]...)
	key := hkdfExpand(shared, salt, []byte("age-encryption.org/v1/X25519"), 32)
	stanza := &Stanza{
		Type: "X25519",
		Args: []string{rawBase64(ephemeral.Public[:])},
	}
	body, err := wrapFileKey(key, stanzaAAD(stanza.Type, stanza.Args), fileKey)
	if err != nil {
		return nil, err
	}
	stanza.Body = body
	return stanza, nil
}

func (i *X25519Identity) Unwrap(stanza *Stanza) ([]byte, error) {
	if stanza.Type != "X25519" || len(stanza.Args) != 1 {
		return nil, ErrIncorrectIdentity
	}
	ephemeral, err := base64.RawStdEncoding.DecodeString(stanza.Args[0])
	if err != nil || len(ephemeral) != 32 {
		return nil, ErrIncorrectIdentity
	}
	shared, err := x25519ScalarMult(i.Secret[:], ephemeral)
	if err != nil {
		return nil, ErrIncorrectIdentity
	}
	salt := append(append([]byte{}, ephemeral...), i.Public[:]...)
	key := hkdfExpand(shared, salt, []byte("age-encryption.org/v1/X25519"), 32)
	return unwrapFileKey(key, stanzaAAD(stanza.Type, stanza.Args), stanza.Body)
}

func (i *X25519Identity) Recipient() (Recipient, error) {
	return &X25519Recipient{Public: i.Public}, nil
}

func (r *SSHEd25519Recipient) Wrap(fileKey []byte) (*Stanza, error) {
	xpub, err := ed25519PublicToX25519(r.Public)
	if err != nil {
		return nil, err
	}
	ephemeral, err := GenerateX25519Identity()
	if err != nil {
		return nil, err
	}
	shared, err := x25519ScalarMult(ephemeral.Secret[:], xpub[:])
	if err != nil {
		return nil, err
	}
	salt := append(append([]byte{}, ephemeral.Public[:]...), xpub[:]...)
	key := hkdfExpand(shared, salt, []byte("age-encryption.org/v1/ssh-ed25519"), 32)
	stanza := &Stanza{
		Type: "ssh-ed25519",
		Args: []string{r.tag(), rawBase64(ephemeral.Public[:])},
	}
	body, err := wrapFileKey(key, stanzaAAD(stanza.Type, stanza.Args), fileKey)
	if err != nil {
		return nil, err
	}
	stanza.Body = body
	return stanza, nil
}

func (i *SSHEd25519Identity) Unwrap(stanza *Stanza) ([]byte, error) {
	if stanza.Type != "ssh-ed25519" || len(stanza.Args) != 2 {
		return nil, ErrIncorrectIdentity
	}
	if stanza.Args[0] != (&SSHEd25519Recipient{Public: i.Public}).tag() {
		return nil, ErrIncorrectIdentity
	}
	ephemeral, err := base64.RawStdEncoding.DecodeString(stanza.Args[1])
	if err != nil || len(ephemeral) != 32 {
		return nil, ErrIncorrectIdentity
	}
	xpriv, err := ed25519PrivateToX25519(i.Private)
	if err != nil {
		return nil, ErrIncorrectIdentity
	}
	xpub, err := ed25519PublicToX25519(i.Public)
	if err != nil {
		return nil, ErrIncorrectIdentity
	}
	shared, err := x25519ScalarMult(xpriv[:], ephemeral)
	if err != nil {
		return nil, ErrIncorrectIdentity
	}
	salt := append(append([]byte{}, ephemeral...), xpub[:]...)
	key := hkdfExpand(shared, salt, []byte("age-encryption.org/v1/ssh-ed25519"), 32)
	return unwrapFileKey(key, stanzaAAD(stanza.Type, stanza.Args), stanza.Body)
}

func (i *SSHEd25519Identity) Recipient() (Recipient, error) {
	return &SSHEd25519Recipient{Public: i.Public}, nil
}

func (r *SSHRSARecipient) Wrap(fileKey []byte) (*Stanza, error) {
	if r.Public.N.BitLen() < 2048 {
		return nil, errors.New("RSA recipient too small")
	}
	body, err := rsa.EncryptOAEP(sha256.New(), rand.Reader, r.Public, fileKey, []byte("age-encryption.org/v1/ssh-rsa"))
	if err != nil {
		return nil, err
	}
	return &Stanza{
		Type: "ssh-rsa",
		Args: []string{r.tag()},
		Body: body,
	}, nil
}

func (i *SSHRSAIdentity) Unwrap(stanza *Stanza) ([]byte, error) {
	if stanza.Type != "ssh-rsa" || len(stanza.Args) != 1 {
		return nil, ErrIncorrectIdentity
	}
	recipient := &SSHRSARecipient{Public: &i.Private.PublicKey, Blob: i.Blob}
	if stanza.Args[0] != recipient.tag() {
		return nil, ErrIncorrectIdentity
	}
	fileKey, err := rsa.DecryptOAEP(sha256.New(), rand.Reader, i.Private, stanza.Body, []byte("age-encryption.org/v1/ssh-rsa"))
	if err != nil {
		return nil, ErrIncorrectIdentity
	}
	if len(fileKey) != fileKeySize {
		return nil, fmt.Errorf("unexpected file key size %d", len(fileKey))
	}
	return fileKey, nil
}

func (i *SSHRSAIdentity) Recipient() (Recipient, error) {
	if i.Private.PublicKey.N.BitLen() < 2048 {
		return nil, errors.New("RSA recipient too small")
	}
	return &SSHRSARecipient{Public: &i.Private.PublicKey, Blob: i.Blob}, nil
}

