package main

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"os"
	"strings"

	"reverseage/ageimpl"

	"golang.org/x/term"
)

const (
	versionString = "v0.0.0-20260414014000-96fce988442d"
	helpText      = `Usage:
    age [--encrypt] (-r RECIPIENT | -R PATH)... [--armor] [-o OUTPUT] [INPUT]
    age [--encrypt] --passphrase [--armor] [-o OUTPUT] [INPUT]
    age --decrypt [-i PATH]... [-o OUTPUT] [INPUT]

Options:
    -e, --encrypt               Encrypt the input to the output. Default if omitted.
    -d, --decrypt               Decrypt the input to the output.
    -o, --output OUTPUT         Write the result to the file at path OUTPUT.
    -a, --armor                 Encrypt to a PEM encoded format.
    -p, --passphrase            Encrypt with a passphrase.
    -r, --recipient RECIPIENT   Encrypt to the specified RECIPIENT. Can be repeated.
    -R, --recipients-file PATH  Encrypt to recipients listed at PATH. Can be repeated.
    -i, --identity PATH         Use the identity file at PATH. Can be repeated.

INPUT defaults to standard input, and OUTPUT defaults to standard output.
If OUTPUT exists, it will be overwritten.

RECIPIENT can be an age public key generated by age-keygen ("age1...")
or an SSH public key ("ssh-ed25519 AAAA...", "ssh-rsa AAAA...").

Recipient files contain one or more recipients, one per line. Empty lines
and lines starting with "#" are ignored as comments. "-" may be used to
read recipients from standard input.

Identity files contain one or more secret keys ("AGE-SECRET-KEY-1..."),
one per line, or an SSH key. Empty lines and lines starting with "#" are
ignored as comments. Passphrase encrypted age files can be used as
identity files. Multiple key files can be provided, and any unused ones
will be ignored. "-" may be used to read identities from standard input.

When --encrypt is specified explicitly, -i can also be used to encrypt to an
identity file symmetrically, instead or in addition to normal recipients.

Example:
    $ age-keygen -o key.txt
    Public key: age1ql3z7hjy54pw3hyww5ayyfg7zqgvc7w3j2elw8zmrj2kg5sfn9aqmcac8p
    $ tar cvz ~/data | age -r age1ql3z7hjy54pw3hyww5ayyfg7zqgvc7w3j2elw8zmrj2kg5sfn9aqmcac8p > data.tar.gz.age
    $ age --decrypt -i key.txt -o data.tar.gz data.tar.gz.age
`
)

type options struct {
	help            bool
	version         bool
	explicitEncrypt bool
	decrypt         bool
	armor           bool
	passphrase      bool
	output          string
	outputSet       bool
	recipients      []string
	recipientFiles  []string
	identities      []string
	plugins         []string
	input           string
	extraInputs     []string
}

type cliError struct {
	message string
	hints   []string
	code    int
}

type usageResult struct {
	message string
	code    int
}

func run(args []string) int {
	if len(args) == 1 {
		printUsage()
		return 1
	}

	opts, usage := parseArgs(args[1:])
	if usage != nil {
		if usage.message != "" {
			fmt.Fprintln(os.Stderr, usage.message)
		}
		printUsage()
		return usage.code
	}
	if opts.help {
		printUsage()
		return 0
	}
	if opts.version {
		fmt.Fprintln(os.Stdout, versionString)
		return 0
	}

	if err := execute(opts); err != nil {
		fmt.Fprintf(os.Stderr, "age: error: %s\n", err.message)
		for _, hint := range err.hints {
			fmt.Fprintf(os.Stderr, "age: hint: %s\n", hint)
		}
		fmt.Fprintln(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report")
		return err.code
	}
	return 0
}

func execute(opts options) *cliError {
	if opts.explicitEncrypt && opts.decrypt {
		return &cliError{message: "-e/--encrypt can't be used with -d/--decrypt", code: 1}
	}
	if len(opts.extraInputs) > 0 {
		inputs := append([]string{opts.input}, opts.extraInputs...)
		return &cliError{
			message: fmt.Sprintf("too many INPUT arguments: %q", strings.Join(inputs, `" "`)),
			hints:   []string{"only a single input file may be specified at a time", "the input file must be specified after all flags"},
			code:    1,
		}
	}

	usesInputStdin := opts.input == "" || opts.input == "-"

	if opts.decrypt {
		if opts.passphrase {
			return &cliError{
				message: "-p/--passphrase can't be used with -d/--decrypt",
				hints:   []string{"note that password protected files are detected automatically"},
				code:    1,
			}
		}
		if opts.armor {
			return &cliError{
				message: "-a/--armor can't be used with -d/--decrypt",
				hints:   []string{"note that armored files are detected automatically, try again without -a/--armor"},
				code:    1,
			}
		}
		if len(opts.recipients) > 0 {
			return &cliError{
				message: "-r/--recipient can't be used with -d/--decrypt",
				hints:   []string{"did you mean to use -i/--identity to specify a private key?"},
				code:    1,
			}
		}
		if len(opts.recipientFiles) > 0 {
			return &cliError{
				message: "-R/--recipients-file can't be used with -d/--decrypt",
				hints:   []string{"did you mean to use -i/--identity to specify a private key?"},
				code:    1,
			}
		}
	} else {
		if (len(opts.identities) > 0 || len(opts.plugins) > 0) && !opts.explicitEncrypt {
			return &cliError{
				message: "-i/--identity and -j can't be used in encryption mode unless symmetric encryption is explicitly selected with -e/--encrypt",
				hints:   []string{"did you forget to specify -d/--decrypt?"},
				code:    1,
			}
		}
		if opts.passphrase {
			switch {
			case len(opts.recipients) > 0:
				return &cliError{message: "-p/--passphrase can't be combined with -r/--recipient", code: 1}
			case len(opts.recipientFiles) > 0:
				return &cliError{message: "-p/--passphrase can't be combined with -R/--recipients-file", code: 1}
			case len(opts.identities) > 0:
				return &cliError{message: "-p/--passphrase can't be combined with -i/--identity", code: 1}
			case len(opts.plugins) > 0:
				return &cliError{message: "-p/--passphrase can't be combined with -j", code: 1}
			}
		}
	}

	prompter := newPrompter()

	if opts.decrypt {
		identities, err := loadIdentitySources(opts.identities, usesInputStdin, prompter)
		if err != nil {
			return err
		}
		if len(opts.plugins) > 0 {
			return pluginError(opts.plugins[0])
		}
		ciphertext, err := readInput(opts.input)
		if err != nil {
			return err
		}
		parsed, parseErr := ageimpl.ParseCiphertext(ciphertext)
		if parseErr != nil {
			return &cliError{message: parseErr.Error(), code: 1}
		}
		if ageimpl.IsPassphraseFile(parsed) {
			if len(identities) > 0 {
				return &cliError{
					message: "file is passphrase-encrypted but identities were specified with -i/--identity or -j",
					hints:   []string{"remove all -i/--identity/-j flags to decrypt passphrase-encrypted files"},
					code:    1,
				}
			}
			passphrase, promptErr := prompter.read("Enter passphrase: ")
			if promptErr != nil {
				return &cliError{message: promptErr.Error(), code: 1}
			}
			plaintext, decErr := ageimpl.DecryptWithPassphrase(parsed, passphrase)
			if errors.Is(decErr, ageimpl.ErrIncorrectPassphrase) {
				return &cliError{message: "incorrect passphrase", code: 1}
			}
			if decErr != nil {
				return &cliError{message: decErr.Error(), code: 1}
			}
			return writeOutput(opts.output, opts.outputSet, plaintext)
		}
		if len(identities) == 0 {
			return &cliError{
				message: "the file is not passphrase-encrypted, identities are required",
				hints:   []string{"specify identities with -i/--identity or -j to decrypt this file"},
				code:    1,
			}
		}
		plaintext, decErr := ageimpl.DecryptWithIdentities(parsed, identities)
		if errors.Is(decErr, ageimpl.ErrIncorrectIdentity) {
			return &cliError{message: "no identity matched any of the recipients", code: 1}
		}
		if decErr != nil {
			return &cliError{message: decErr.Error(), code: 1}
		}
		return writeOutput(opts.output, opts.outputSet, plaintext)
	}

	recipients, err := loadRecipients(opts.recipients, opts.recipientFiles, usesInputStdin)
	if err != nil {
		return err
	}
	if opts.explicitEncrypt && len(opts.identities) > 0 {
		identityRecipients, idErr := identityRecipients(opts.identities, usesInputStdin, prompter)
		if idErr != nil {
			return idErr
		}
		recipients = append(recipients, identityRecipients...)
	}
	if len(opts.plugins) > 0 {
		return pluginWrapError(opts.plugins[0], len(recipients))
	}

	plaintext, inErr := readInput(opts.input)
	if inErr != nil {
		return inErr
	}
	if !opts.passphrase {
		if len(recipients) == 0 {
			return &cliError{
				message: "missing recipients",
				hints:   []string{"did you forget to specify -r/--recipient, -R/--recipients-file or -p/--passphrase?"},
				code:    1,
			}
		}
		if !opts.outputSet && !opts.armor && term.IsTerminal(int(os.Stdout.Fd())) {
			return &cliError{
				message: "refusing to output binary to the terminal",
				hints:   []string{"did you mean to use -a/--armor?", `force anyway with "-o -"`},
				code:    1,
			}
		}
		ciphertext, encErr := ageimpl.Encrypt(plaintext, recipients)
		if encErr != nil {
			return &cliError{message: encErr.Error(), code: 1}
		}
		if opts.armor {
			ciphertext = ageimpl.Armor(ciphertext)
		}
		return writeOutput(opts.output, opts.outputSet, ciphertext)
	}

	passphrase, promptErr := promptEncryptPassphrase(prompter)
	if promptErr != nil {
		return promptErr
	}
	ciphertext, encErr := ageimpl.EncryptWithPassphrase(plaintext, passphrase, 18)
	if encErr != nil {
		return &cliError{message: encErr.Error(), code: 1}
	}
	if opts.armor {
		ciphertext = ageimpl.Armor(ciphertext)
	}
	return writeOutput(opts.output, opts.outputSet, ciphertext)
}

func parseArgs(args []string) (options, *usageResult) {
	var opts options
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if opts.input != "" {
			opts.extraInputs = append(opts.extraInputs, arg)
			continue
		}
		if arg == "--" {
			if i+1 < len(args) {
				opts.input = args[i+1]
				opts.extraInputs = append(opts.extraInputs, args[i+2:]...)
			}
			break
		}
		if arg == "-" || !strings.HasPrefix(arg, "-") {
			opts.input = arg
			continue
		}
		switch {
		case arg == "-h" || arg == "--help":
			opts.help = true
		case arg == "--version":
			opts.version = true
		case arg == "-e" || arg == "--encrypt":
			opts.explicitEncrypt = true
		case arg == "-d" || arg == "--decrypt":
			opts.decrypt = true
		case arg == "-a" || arg == "--armor":
			opts.armor = true
		case arg == "-p" || arg == "--passphrase":
			opts.passphrase = true
		case arg == "-o" || arg == "--output":
			val, next, ok := optionValue(arg, args, i)
			if !ok {
				return opts, &usageResult{message: missingArgMessage(arg), code: 2}
			}
			i = next
			opts.output = val
			opts.outputSet = true
		case arg == "-r" || arg == "--recipient":
			val, next, ok := optionValue(arg, args, i)
			if !ok {
				return opts, &usageResult{message: missingArgMessage(arg), code: 2}
			}
			i = next
			opts.recipients = append(opts.recipients, val)
		case arg == "-R" || arg == "--recipients-file":
			val, next, ok := optionValue(arg, args, i)
			if !ok {
				return opts, &usageResult{message: missingArgMessage(arg), code: 2}
			}
			i = next
			opts.recipientFiles = append(opts.recipientFiles, val)
		case arg == "-i" || arg == "--identity":
			val, next, ok := optionValue(arg, args, i)
			if !ok {
				return opts, &usageResult{message: missingArgMessage(arg), code: 2}
			}
			i = next
			opts.identities = append(opts.identities, val)
		case arg == "-j":
			val, next, ok := optionValue(arg, args, i)
			if !ok {
				return opts, &usageResult{message: missingArgMessage(arg), code: 2}
			}
			i = next
			opts.plugins = append(opts.plugins, val)
		case strings.HasPrefix(arg, "-o="), strings.HasPrefix(arg, "--output="):
			opts.output = arg[strings.IndexByte(arg, '=')+1:]
			opts.outputSet = true
		case strings.HasPrefix(arg, "-r="), strings.HasPrefix(arg, "--recipient="):
			opts.recipients = append(opts.recipients, arg[strings.IndexByte(arg, '=')+1:])
		case strings.HasPrefix(arg, "-R="), strings.HasPrefix(arg, "--recipients-file="):
			opts.recipientFiles = append(opts.recipientFiles, arg[strings.IndexByte(arg, '=')+1:])
		case strings.HasPrefix(arg, "-i="), strings.HasPrefix(arg, "--identity="):
			opts.identities = append(opts.identities, arg[strings.IndexByte(arg, '=')+1:])
		case strings.HasPrefix(arg, "-j="):
			opts.plugins = append(opts.plugins, arg[strings.IndexByte(arg, '=')+1:])
		default:
			return opts, &usageResult{message: fmt.Sprintf("flag provided but not defined: %s", displayFlag(arg)), code: 2}
		}
	}
	return opts, nil
}

func optionValue(flag string, args []string, index int) (string, int, bool) {
	if eq := strings.IndexByte(flag, '='); eq >= 0 {
		return flag[eq+1:], index, true
	}
	if index+1 >= len(args) {
		return "", index, false
	}
	return args[index+1], index + 1, true
}

func displayFlag(flag string) string {
	return "-" + strings.TrimLeft(flag, "-")
}

func missingArgMessage(flag string) string {
	return fmt.Sprintf("flag needs an argument: %s", displayFlag(flag))
}

func printUsage() {
	fmt.Fprint(os.Stderr, helpText)
}

func readInput(path string) ([]byte, *cliError) {
	if path == "" || path == "-" {
		data, err := io.ReadAll(os.Stdin)
		if err != nil {
			return nil, &cliError{message: fmt.Sprintf("failed to read input: %v", err), code: 1}
		}
		return data, nil
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, &cliError{message: fmt.Sprintf("failed to open input file %q: %v", path, err), code: 1}
	}
	return data, nil
}

func writeOutput(path string, outputSet bool, data []byte) *cliError {
	if !outputSet || path == "-" {
		if _, err := os.Stdout.Write(data); err != nil {
			return &cliError{message: fmt.Sprintf("failed to write output: %v", err), code: 1}
		}
		return nil
	}
	if err := os.WriteFile(path, data, 0o666); err != nil {
		return &cliError{message: fmt.Sprintf("failed to open output file %q: %v", path, err), code: 1}
	}
	return nil
}

func loadRecipients(direct []string, files []string, usesInputStdin bool) ([]ageimpl.Recipient, *cliError) {
	var recipients []ageimpl.Recipient
	for _, item := range direct {
		recipient, err := parseRecipientValue(item)
		if err != nil {
			return nil, &cliError{message: err.Error(), code: 1}
		}
		recipients = append(recipients, recipient)
	}
	for _, path := range files {
		items, warn, err := loadRecipientFile(path, usesInputStdin)
		for _, w := range warn {
			fmt.Fprintf(os.Stderr, "age: warning: %s\n", w)
		}
		if err != nil {
			return nil, err
		}
		recipients = append(recipients, items...)
	}
	return recipients, nil
}

func loadRecipientFile(path string, usesInputStdin bool) ([]ageimpl.Recipient, []string, *cliError) {
	if path == "-" && usesInputStdin {
		return nil, nil, &cliError{message: `failed to parse recipient file "-": standard input is used for multiple purposes`, code: 1}
	}
	data, readErr := readNamedOrStdin(path)
	if readErr != nil {
		return nil, nil, &cliError{message: fmt.Sprintf("failed to parse recipient file %q: %s", path, readErr), code: 1}
	}
	lines := splitLines(data)
	var recipients []ageimpl.Recipient
	var warnings []string
	for idx, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}
		recipient, err := parseRecipientValue(trimmed)
		if err == nil {
			recipients = append(recipients, recipient)
			continue
		}
		if isUnsupportedSSH(trimmed) {
			keyType := strings.Fields(trimmed)[0]
			warnings = append(warnings, fmt.Sprintf("recipients file %q: ignoring unsupported SSH key of type %q at line %d", path, keyType, idx+1))
			continue
		}
		return nil, warnings, &cliError{message: fmt.Sprintf("failed to parse recipient file %q: %q: malformed recipient at line %d", path, path, idx+1), code: 1}
	}
	if len(recipients) == 0 {
		return nil, warnings, &cliError{message: fmt.Sprintf("failed to parse recipient file %q: %q: no recipients found", path, path), code: 1}
	}
	return recipients, warnings, nil
}

func parseRecipientValue(value string) (ageimpl.Recipient, error) {
	if strings.HasPrefix(value, "age1") {
		recipient, err := ageimpl.ParseRecipient(value)
		if err == nil {
			return recipient, nil
		}
	}
	if strings.HasPrefix(value, "ssh-") {
		recipient, err := ageimpl.ParseAuthorizedRecipient(value)
		if err == nil {
			return recipient, nil
		}
	}
	return nil, fmt.Errorf("unknown recipient type: %q", value)
}

func identityRecipients(paths []string, usesInputStdin bool, prompter *prompter) ([]ageimpl.Recipient, *cliError) {
	identities, err := loadIdentitySources(paths, usesInputStdin, prompter)
	if err != nil {
		return nil, err
	}
	recipients := make([]ageimpl.Recipient, 0, len(identities))
	for _, identity := range identities {
		recipient, convErr := identity.Recipient()
		if convErr != nil {
			return nil, &cliError{message: convErr.Error(), code: 1}
		}
		recipients = append(recipients, recipient)
	}
	return recipients, nil
}

func loadIdentitySources(paths []string, usesInputStdin bool, prompter *prompter) ([]ageimpl.Identity, *cliError) {
	var identities []ageimpl.Identity
	for _, path := range paths {
		items, err := loadIdentityFile(path, usesInputStdin, prompter)
		if err != nil {
			return nil, err
		}
		identities = append(identities, items...)
	}
	return identities, nil
}

func loadIdentityFile(path string, usesInputStdin bool, prompter *prompter) ([]ageimpl.Identity, *cliError) {
	if path == "-" && usesInputStdin {
		return nil, &cliError{message: `reading "-": standard input is used for multiple purposes`, code: 1}
	}
	data, readErr := readNamedOrStdin(path)
	if readErr != nil {
		return nil, &cliError{message: fmt.Sprintf("reading %q: %s", path, readErr), code: 1}
	}
	if isAgeCiphertext(data) {
		parsed, err := ageimpl.ParseCiphertext(data)
		if err != nil {
			return nil, &cliError{message: err.Error(), code: 1}
		}
		passphrase, promptErr := prompter.read(fmt.Sprintf("Enter passphrase for identity file %q: ", path))
		if promptErr != nil {
			return nil, &cliError{message: promptErr.Error(), code: 1}
		}
		plaintext, decErr := ageimpl.DecryptWithPassphrase(parsed, passphrase)
		if errors.Is(decErr, ageimpl.ErrIncorrectPassphrase) {
			return nil, &cliError{message: "failed to decrypt identity file: incorrect passphrase", code: 1}
		}
		if decErr != nil {
			return nil, &cliError{message: fmt.Sprintf("failed to decrypt identity file: %v", decErr), code: 1}
		}
		identities, parseErr := parseLineIdentities(plaintext)
		if parseErr != nil {
			return nil, &cliError{message: parseErr.Error(), code: 1}
		}
		return identities, nil
	}
	if bytes.HasPrefix(data, []byte("-----BEGIN ")) {
		identity, err := ageimpl.ParseSSHIdentity(data)
		if err == nil {
			return []ageimpl.Identity{identity}, nil
		}
	}
	identities, parseErr := parseLineIdentities(data)
	if parseErr != nil {
		return nil, &cliError{message: fmt.Sprintf("reading %q: failed to read %q: %s", path, path, parseErr.Error()), code: 1}
	}
	return identities, nil
}

func parseLineIdentities(data []byte) ([]ageimpl.Identity, error) {
	lines := splitLines(data)
	var identities []ageimpl.Identity
	for idx, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}
		identity, err := ageimpl.ParseIdentity(trimmed)
		if err != nil {
			return nil, fmt.Errorf("error at line %d: unknown identity type", idx+1)
		}
		identities = append(identities, identity)
	}
	if len(identities) == 0 {
		return nil, errors.New("no identities found")
	}
	return identities, nil
}

func splitLines(data []byte) []string {
	text := strings.ReplaceAll(string(data), "\r\n", "\n")
	return strings.Split(text, "\n")
}

func isAgeCiphertext(data []byte) bool {
	return bytes.HasPrefix(data, []byte("age-encryption.org/v1\n")) || bytes.HasPrefix(data, []byte("-----BEGIN AGE ENCRYPTED FILE-----"))
}

func readNamedOrStdin(path string) ([]byte, string) {
	if path == "-" {
		data, err := io.ReadAll(os.Stdin)
		if err != nil {
			return nil, fmt.Sprintf("failed to read %q: %v", path, err)
		}
		return data, ""
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Sprintf("failed to open file: %v", err)
	}
	return data, ""
}

func isUnsupportedSSH(line string) bool {
	fields := strings.Fields(line)
	if len(fields) == 0 {
		return false
	}
	switch fields[0] {
	case "ecdsa-sha2-nistp256", "ecdsa-sha2-nistp384", "ecdsa-sha2-nistp521":
		return true
	case "ssh-rsa":
		recipient, err := ageimpl.ParseAuthorizedRecipient(line)
		return err != nil
	default:
		return false
	}
}

func pluginError(name string) *cliError {
	return &cliError{
		message: fmt.Sprintf(`%s plugin: couldn't start plugin: %q plugin not found: exec: %q: executable file not found in $PATH`, name, name, "age-plugin-"+name),
		hints: []string{
			fmt.Sprintf("you might want to install the %q plugin", name),
			"visit https://age-encryption.org/awesome#plugins for a list of available plugins",
		},
		code: 1,
	}
}

func pluginWrapError(name string, index int) *cliError {
	err := pluginError(name)
	err.message = fmt.Sprintf("failed to wrap key for recipient #%d: %s", index, err.message)
	return err
}

