package main

import (
	"crypto/rand"
	"encoding/binary"
	"fmt"
	"os"
	"strings"

	"golang.org/x/term"
)

type prompter struct {
	tty      *os.File
	ownsFile bool
}

func newPrompter() *prompter {
	return &prompter{}
}

func (p *prompter) read(prompt string) (string, error) {
	tty, err := p.terminal()
	if err != nil {
		return "", err
	}
	if _, err := fmt.Fprint(tty, prompt); err != nil {
		return "", fmt.Errorf("could not read passphrase: %v", err)
	}
	secret, err := term.ReadPassword(int(tty.Fd()))
	if err != nil {
		return "", fmt.Errorf("could not read passphrase: %v", err)
	}
	fmt.Fprint(tty, "\r\n\033[F\033[K")
	return string(secret), nil
}

func (p *prompter) say(msg string) error {
	tty, err := p.terminal()
	if err != nil {
		return err
	}
	_, err = fmt.Fprintln(tty, msg)
	return err
}

func (p *prompter) terminal() (*os.File, error) {
	if p.tty != nil {
		return p.tty, nil
	}
	if term.IsTerminal(int(os.Stdin.Fd())) {
		p.tty = os.Stdin
		return p.tty, nil
	}
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		return nil, fmt.Errorf("could not read passphrase: standard input is not a terminal, and /dev/tty is not available: %v", err)
	}
	p.tty = tty
	p.ownsFile = true
	return p.tty, nil
}

func promptEncryptPassphrase(p *prompter) (string, *cliError) {
	first, err := p.read("Enter passphrase (leave empty to autogenerate a secure one): ")
	if err != nil {
		return "", &cliError{message: err.Error(), code: 1}
	}
	if first == "" {
		passphrase := autogeneratedPassphrase()
		if sayErr := p.say(fmt.Sprintf("age: using autogenerated passphrase %q", passphrase)); sayErr != nil {
			return "", &cliError{message: sayErr.Error(), code: 1}
		}
		return passphrase, nil
	}
	second, err := p.read("Confirm passphrase: ")
	if err != nil {
		return "", &cliError{message: err.Error(), code: 1}
	}
	if first != second {
		return "", &cliError{message: "passphrases didn't match", code: 1}
	}
	return first, nil
}

func autogeneratedPassphrase() string {
	words := []string{
		"amber", "ankle", "breeze", "bridge", "cactus", "candle", "canyon", "copper",
		"cradle", "cricket", "daring", "dawn", "ember", "fable", "fossil", "gentle",
		"glider", "harbor", "honey", "jungle", "lantern", "meadow", "mistake", "ocean",
		"orchard", "puppy", "quartz", "raven", "ripple", "sail", "shelter", "slim",
		"sprout", "sunset", "thistle", "valley", "velvet", "wander", "willow", "zephyr",
	}
	parts := make([]string, 10)
	var buf [8]byte
	for i := range parts {
		if _, err := rand.Read(buf[:]); err != nil {
			parts[i] = words[i%len(words)]
			continue
		}
		parts[i] = words[binary.BigEndian.Uint64(buf[:])%uint64(len(words))]
	}
	return strings.Join(parts, "-")
}

