package ageimpl

import (
	"bytes"
	"crypto/ed25519"
	"crypto/rsa"
	"crypto/x509"
	"encoding/base64"
	"encoding/binary"
	"encoding/pem"
	"errors"
	"fmt"
	"math/big"
	"strings"
)

func ParseAuthorizedRecipient(line string) (Recipient, error) {
	fields := strings.Fields(strings.TrimSpace(line))
	if len(fields) < 2 {
		return nil, fmt.Errorf("unknown recipient type: %q", line)
	}
	keyType := fields[0]
	blob, err := base64.StdEncoding.DecodeString(fields[1])
	if err != nil {
		return nil, fmt.Errorf("unknown recipient type: %q", line)
	}
	r := sshReader{data: blob}
	innerType, err := r.readString()
	if err != nil || string(innerType) != keyType {
		return nil, fmt.Errorf("unknown recipient type: %q", line)
	}
	switch keyType {
	case "ssh-ed25519":
		pub, err := r.readString()
		if err != nil || len(pub) != ed25519.PublicKeySize || !r.done() {
			return nil, fmt.Errorf("unknown recipient type: %q", line)
		}
		return &SSHEd25519Recipient{Public: ed25519.PublicKey(pub)}, nil
	case "ssh-rsa":
		e, err := r.readMPInt()
		if err != nil {
			return nil, fmt.Errorf("unknown recipient type: %q", line)
		}
		n, err := r.readMPInt()
		if err != nil || !r.done() {
			return nil, fmt.Errorf("unknown recipient type: %q", line)
		}
		pub := &rsa.PublicKey{N: n, E: int(e.Int64())}
		if pub.N.BitLen() < 2048 {
			return nil, fmt.Errorf("unsupported SSH key of type %q", keyType)
		}
		return &SSHRSARecipient{Public: pub, Blob: append([]byte{}, blob...)}, nil
	default:
		return nil, fmt.Errorf("unsupported SSH key of type %q", keyType)
	}
}

func ParseSSHIdentity(data []byte) (Identity, error) {
	block, _ := pem.Decode(data)
	if block == nil {
		return nil, errors.New("unknown identity type")
	}
	switch block.Type {
	case "OPENSSH PRIVATE KEY":
		return parseOpenSSHPrivateKey(block.Bytes)
	case "RSA PRIVATE KEY":
		priv, err := x509.ParsePKCS1PrivateKey(block.Bytes)
		if err != nil {
			return nil, err
		}
		return &SSHRSAIdentity{Private: priv, Blob: sshBlobForRSA(&priv.PublicKey)}, nil
	case "PRIVATE KEY":
		key, err := x509.ParsePKCS8PrivateKey(block.Bytes)
		if err != nil {
			return nil, err
		}
		switch k := key.(type) {
		case ed25519.PrivateKey:
			pub := k.Public().(ed25519.PublicKey)
			return &SSHEd25519Identity{Private: k, Public: pub}, nil
		case *rsa.PrivateKey:
			return &SSHRSAIdentity{Private: k, Blob: sshBlobForRSA(&k.PublicKey)}, nil
		default:
			return nil, errors.New("unknown identity type")
		}
	default:
		return nil, errors.New("unknown identity type")
	}
}

func parseOpenSSHPrivateKey(data []byte) (Identity, error) {
	const magic = "openssh-key-v1\x00"
	if !bytes.HasPrefix(data, []byte(magic)) {
		return nil, errors.New("unknown identity type")
	}
	r := sshReader{data: data[len(magic):]}
	cipherName, err := r.readString()
	if err != nil {
		return nil, err
	}
	kdfName, err := r.readString()
	if err != nil {
		return nil, err
	}
	kdfOpts, err := r.readString()
	if err != nil {
		return nil, err
	}
	nKeys, err := r.readUint32()
	if err != nil {
		return nil, err
	}
	if string(cipherName) != "none" || string(kdfName) != "none" || len(kdfOpts) != 0 || nKeys == 0 {
		return nil, errors.New("unknown identity type")
	}
	for i := uint32(0); i < nKeys; i++ {
		if _, err := r.readString(); err != nil {
			return nil, err
		}
	}
	privateSection, err := r.readString()
	if err != nil {
		return nil, err
	}

	pr := sshReader{data: privateSection}
	check1, err := pr.readUint32()
	if err != nil {
		return nil, err
	}
	check2, err := pr.readUint32()
	if err != nil || check1 != check2 {
		return nil, errors.New("unknown identity type")
	}
	keyType, err := pr.readString()
	if err != nil {
		return nil, err
	}
	switch string(keyType) {
	case "ssh-ed25519":
		pub, err := pr.readString()
		if err != nil {
			return nil, err
		}
		priv, err := pr.readString()
		if err != nil {
			return nil, err
		}
		if _, err := pr.readString(); err != nil {
			return nil, err
		}
		if len(pub) != ed25519.PublicKeySize || len(priv) != ed25519.PrivateKeySize {
			return nil, errors.New("unknown identity type")
		}
		return &SSHEd25519Identity{
			Private: ed25519.PrivateKey(append([]byte{}, priv...)),
			Public:  ed25519.PublicKey(append([]byte{}, pub...)),
		}, nil
	case "ssh-rsa":
		n, err := pr.readMPInt()
		if err != nil {
			return nil, err
		}
		e, err := pr.readMPInt()
		if err != nil {
			return nil, err
		}
		d, err := pr.readMPInt()
		if err != nil {
			return nil, err
		}
		if _, err := pr.readMPInt(); err != nil { // iqmp
			return nil, err
		}
		p, err := pr.readMPInt()
		if err != nil {
			return nil, err
		}
		q, err := pr.readMPInt()
		if err != nil {
			return nil, err
		}
		if _, err := pr.readString(); err != nil {
			return nil, err
		}
		priv := &rsa.PrivateKey{
			PublicKey: rsa.PublicKey{N: n, E: int(e.Int64())},
			D:         d,
			Primes:    []*big.Int{p, q},
		}
		if err := priv.Validate(); err != nil {
			return nil, err
		}
		priv.Precompute()
		return &SSHRSAIdentity{Private: priv, Blob: sshBlobForRSA(&priv.PublicKey)}, nil
	default:
		return nil, errors.New("unknown identity type")
	}
}

func sshBlobForRSA(pub *rsa.PublicKey) []byte {
	return marshalSSHString([]byte("ssh-rsa"), marshalMPInt(big.NewInt(int64(pub.E))), marshalMPInt(pub.N))
}

func marshalSSHString(parts ...[]byte) []byte {
	var out []byte
	for _, part := range parts {
		var lenBuf [4]byte
		binary.BigEndian.PutUint32(lenBuf[:], uint32(len(part)))
		out = append(out, lenBuf[:]...)
		out = append(out, part...)
	}
	return out
}

func marshalMPInt(v *big.Int) []byte {
	if v.Sign() == 0 {
		return nil
	}
	b := v.Bytes()
	if b[0]&0x80 != 0 {
		return append([]byte{0}, b...)
	}
	return b
}

type sshReader struct {
	data []byte
}

func (r *sshReader) readUint32() (uint32, error) {
	if len(r.data) < 4 {
		return 0, errors.New("unknown identity type")
	}
	v := binary.BigEndian.Uint32(r.data[:4])
	r.data = r.data[4:]
	return v, nil
}

func (r *sshReader) readString() ([]byte, error) {
	n, err := r.readUint32()
	if err != nil {
		return nil, err
	}
	if uint32(len(r.data)) < n {
		return nil, errors.New("unknown identity type")
	}
	out := append([]byte{}, r.data[:n]...)
	r.data = r.data[n:]
	return out, nil
}

func (r *sshReader) readMPInt() (*big.Int, error) {
	b, err := r.readString()
	if err != nil {
		return nil, err
	}
	if len(b) == 0 {
		return big.NewInt(0), nil
	}
	if b[0]&0x80 != 0 {
		return nil, errors.New("unknown identity type")
	}
	return new(big.Int).SetBytes(b), nil
}

func (r *sshReader) done() bool {
	return len(r.data) == 0
}

