package ageimpl

import (
	"crypto/hmac"
	"crypto/sha256"
)

func hkdfExpandSHA256(secret, salt, info []byte, size int) []byte {
	if salt == nil {
		salt = make([]byte, sha256.Size)
	}
	extract := hmac.New(sha256.New, salt)
	extract.Write(secret)
	prk := extract.Sum(nil)

	var out []byte
	var prev []byte
	counter := byte(1)
	for len(out) < size {
		h := hmac.New(sha256.New, prk)
		h.Write(prev)
		h.Write(info)
		h.Write([]byte{counter})
		prev = h.Sum(nil)
		out = append(out, prev...)
		counter++
	}
	return out[:size]
}

