package ageimpl

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/binary"
	"errors"
)

func scryptKeySHA256(password, salt []byte, N, r, p, keyLen int) ([]byte, error) {
	if N <= 1 || N&(N-1) != 0 {
		return nil, errors.New("invalid scrypt N parameter")
	}
	if r <= 0 || p <= 0 || keyLen <= 0 {
		return nil, errors.New("invalid scrypt parameters")
	}

	B := pbkdf2SHA256(password, salt, 1, p*128*r)
	for i := 0; i < p; i++ {
		romix(B[i*128*r:(i+1)*128*r], r, N)
	}
	return pbkdf2SHA256(password, B, 1, keyLen), nil
}

func pbkdf2SHA256(password, salt []byte, iterations, keyLen int) []byte {
	hLen := sha256.Size
	numBlocks := (keyLen + hLen - 1) / hLen
	out := make([]byte, 0, numBlocks*hLen)
	var counter [4]byte
	for block := 1; block <= numBlocks; block++ {
		binary.BigEndian.PutUint32(counter[:], uint32(block))
		mac := hmac.New(sha256.New, password)
		mac.Write(salt)
		mac.Write(counter[:])
		u := mac.Sum(nil)
		t := append([]byte{}, u...)
		for i := 1; i < iterations; i++ {
			mac = hmac.New(sha256.New, password)
			mac.Write(u)
			u = mac.Sum(nil)
			for j := range t {
				t[j] ^= u[j]
			}
		}
		out = append(out, t...)
	}
	return out[:keyLen]
}

func romix(block []byte, r, N int) {
	X := bytesToWords(block)
	V := make([][]uint32, N)
	for i := 0; i < N; i++ {
		V[i] = append([]uint32(nil), X...)
		blockMix(X, r)
	}
	for i := 0; i < N; i++ {
		j := integerify(X, r) & uint64(N-1)
		xorWords(X, V[j])
		blockMix(X, r)
	}
	wordsToBytes(X, block)
}

func bytesToWords(b []byte) []uint32 {
	w := make([]uint32, len(b)/4)
	for i := range w {
		w[i] = binary.LittleEndian.Uint32(b[i*4:])
	}
	return w
}

func wordsToBytes(words []uint32, out []byte) {
	for i, w := range words {
		binary.LittleEndian.PutUint32(out[i*4:], w)
	}
}

func xorWords(dst, src []uint32) {
	for i := range dst {
		dst[i] ^= src[i]
	}
}

func integerify(X []uint32, r int) uint64 {
	idx := (2*r - 1) * 16
	return uint64(X[idx]) | uint64(X[idx+1])<<32
}

func blockMix(B []uint32, r int) {
	X := append([]uint32(nil), B[(2*r-1)*16:(2*r)*16]...)
	Y := make([]uint32, len(B))
	for i := 0; i < 2*r; i++ {
		start := i * 16
		for j := 0; j < 16; j++ {
			X[j] ^= B[start+j]
		}
		salsa208(X)
		copy(Y[start:start+16], X)
	}
	for i := 0; i < r; i++ {
		copy(B[i*16:(i+1)*16], Y[(2*i)*16:(2*i+1)*16])
		copy(B[(i+r)*16:(i+r+1)*16], Y[(2*i+1)*16:(2*i+2)*16])
	}
}

func salsa208(B []uint32) {
	x := append([]uint32(nil), B...)
	for i := 0; i < 8; i += 2 {
		x[4] ^= rotl(x[0]+x[12], 7)
		x[8] ^= rotl(x[4]+x[0], 9)
		x[12] ^= rotl(x[8]+x[4], 13)
		x[0] ^= rotl(x[12]+x[8], 18)

		x[9] ^= rotl(x[5]+x[1], 7)
		x[13] ^= rotl(x[9]+x[5], 9)
		x[1] ^= rotl(x[13]+x[9], 13)
		x[5] ^= rotl(x[1]+x[13], 18)

		x[14] ^= rotl(x[10]+x[6], 7)
		x[2] ^= rotl(x[14]+x[10], 9)
		x[6] ^= rotl(x[2]+x[14], 13)
		x[10] ^= rotl(x[6]+x[2], 18)

		x[3] ^= rotl(x[15]+x[11], 7)
		x[7] ^= rotl(x[3]+x[15], 9)
		x[11] ^= rotl(x[7]+x[3], 13)
		x[15] ^= rotl(x[11]+x[7], 18)

		x[1] ^= rotl(x[0]+x[3], 7)
		x[2] ^= rotl(x[1]+x[0], 9)
		x[3] ^= rotl(x[2]+x[1], 13)
		x[0] ^= rotl(x[3]+x[2], 18)

		x[6] ^= rotl(x[5]+x[4], 7)
		x[7] ^= rotl(x[6]+x[5], 9)
		x[4] ^= rotl(x[7]+x[6], 13)
		x[5] ^= rotl(x[4]+x[7], 18)

		x[11] ^= rotl(x[10]+x[9], 7)
		x[8] ^= rotl(x[11]+x[10], 9)
		x[9] ^= rotl(x[8]+x[11], 13)
		x[10] ^= rotl(x[9]+x[8], 18)

		x[12] ^= rotl(x[15]+x[14], 7)
		x[13] ^= rotl(x[12]+x[15], 9)
		x[14] ^= rotl(x[13]+x[12], 13)
		x[15] ^= rotl(x[14]+x[13], 18)
	}
	for i := range B {
		B[i] += x[i]
	}
}

func rotl(v uint32, n uint) uint32 {
	return (v << n) | (v >> (32 - n))
}

