package ageimpl

import (
	"bytes"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"os"
	"testing"
)

type macProbeSample struct {
	name       string
	fileKey    []byte
	headerMAC  []byte
	header     []byte
	stanzas    []byte
	headerDash []byte
	headerNL   []byte
	intro      []byte
	payloadTag []byte
	payloadKey []byte
}

func TestMacProbeSearch(t *testing.T) {
	identity, err := ParseIdentity("AGE-SECRET-KEY-1N9JEPW6DWJ0ZQUDX63F5A03GX8QUW7PXDE39N8UYF82VZ9PC8UFS3M7XA9")
	if err != nil {
		t.Fatal(err)
	}

	names := []string{
		"/workspace/tmp_probe/plain.native.age",
		"/workspace/tmp_probe/macprobe1.age",
		"/workspace/tmp_probe/macprobe2.age",
		"/workspace/tmp_probe/macprobe3.age",
	}

	var samples []macProbeSample
	for _, name := range names {
		data, err := os.ReadFile(name)
		if err != nil {
			t.Fatal(err)
		}
		parsed, err := ParseCiphertext(data)
		if err != nil {
			t.Fatal(err)
		}
		if len(parsed.Header) != 1 {
			t.Fatalf("%s: unexpected header count %d", name, len(parsed.Header))
		}
		stanza := parsed.Header[0]
		ephemeral, err := base64.RawStdEncoding.DecodeString(stanza.Args[0])
		if err != nil {
			t.Fatal(err)
		}
		shared, err := x25519ScalarMult(identity.Secret[:], ephemeral)
		if err != nil {
			t.Fatal(err)
		}
		salt := append(append([]byte{}, ephemeral...), identity.Public[:]...)
		key := hkdfExpandSHA256(shared, salt, []byte("age-encryption.org/v1/X25519"), 32)
		fileKey, err := unwrapFileKey(key, nil, stanza.Body)
		if err != nil {
			t.Fatal(err)
		}

		intro := []byte(headerIntro + "\n")
		stanzas := headerStanzasOnly(parsed.HeaderPrefix)
		headerDash := append(append([]byte{}, parsed.HeaderPrefix...), []byte("--- ")...)
		headerNL := append(append([]byte{}, parsed.HeaderPrefix...), '\n')
		payloadTag := parsed.Payload[:16]
		payloadKey := hkdfExpandSHA256(fileKey, payloadTag, []byte("payload"), 32)
		samples = append(samples, macProbeSample{
			name:       name,
			fileKey:    fileKey,
			headerMAC:  parsed.HeaderMAC,
			header:     parsed.HeaderPrefix,
			stanzas:    stanzas,
			headerDash: headerDash,
			headerNL:   headerNL,
			intro:      intro,
			payloadTag: payloadTag,
			payloadKey: payloadKey,
		})
	}

	consts := []struct {
		name string
		data []byte
	}{
		{"nil", nil},
		{"empty", []byte{}},
		{"header", []byte("header")},
		{"payload", []byte("payload")},
		{"mac", []byte("mac")},
		{"X25519", []byte("X25519")},
		{"v1", []byte("age-encryption.org/v1")},
		{"v1/header", []byte("age-encryption.org/v1/header")},
		{"v1/payload", []byte("age-encryption.org/v1/payload")},
		{"v1/mac", []byte("age-encryption.org/v1/mac")},
		{"v1/X25519", []byte("age-encryption.org/v1/X25519")},
	}

	type baseVal struct {
		name string
		get  func(macProbeSample) []byte
	}
	bases := []baseVal{
		{"fileKey", func(s macProbeSample) []byte { return s.fileKey }},
		{"payloadKey", func(s macProbeSample) []byte { return s.payloadKey }},
		{"payloadTag", func(s macProbeSample) []byte { return s.payloadTag }},
		{"header", func(s macProbeSample) []byte { return s.header }},
		{"stanzas", func(s macProbeSample) []byte { return s.stanzas }},
		{"headerDash", func(s macProbeSample) []byte { return s.headerDash }},
		{"headerNL", func(s macProbeSample) []byte { return s.headerNL }},
		{"intro", func(s macProbeSample) []byte { return s.intro }},
	}
	for _, c := range consts {
		c := c
		bases = append(bases, baseVal{
			name: c.name,
			get: func(macProbeSample) []byte {
				return c.data
			},
		})
	}

	type expr struct {
		name string
		get  func(macProbeSample) []byte
	}

	var msgs []expr
	for _, b := range bases {
		b := b
		msgs = append(msgs, expr{name: b.name, get: b.get})
	}

	var keys []expr
	seen := map[string]bool{}
	addKey := func(name string, fn func(macProbeSample) []byte) {
		if seen[name] {
			return
		}
		seen[name] = true
		keys = append(keys, expr{name: name, get: fn})
	}
	for _, b := range bases {
		b := b
		addKey(b.name, b.get)
		addKey("sha256("+b.name+")", func(s macProbeSample) []byte {
			sum := sha256.Sum256(b.get(s))
			return sum[:]
		})
	}
	for _, a := range bases {
		for _, b := range bases {
			a := a
			b := b
			addKey("sha256("+a.name+"+"+b.name+")", func(s macProbeSample) []byte {
				h := sha256.New()
				h.Write(a.get(s))
				h.Write(b.get(s))
				return h.Sum(nil)
			})
			addKey("hmac("+a.name+","+b.name+")", func(s macProbeSample) []byte {
				m := hmac.New(sha256.New, a.get(s))
				m.Write(b.get(s))
				return m.Sum(nil)
			})
		}
	}
	for _, secret := range bases {
		for _, salt := range bases {
			for _, info := range bases {
				secret := secret
				salt := salt
				info := info
				addKey("hkdf("+secret.name+","+salt.name+","+info.name+")", func(s macProbeSample) []byte {
					return hkdfExpandSHA256(secret.get(s), salt.get(s), info.get(s), 32)
				})
			}
		}
	}

	type match struct {
		final string
	}
	var matches []match

	for _, keyExpr := range keys {
		for _, msgExpr := range msgs {
			ok := true
			for _, sample := range samples {
				m := hmac.New(sha256.New, keyExpr.get(sample))
				m.Write(msgExpr.get(sample))
				if !hmac.Equal(m.Sum(nil), sample.headerMAC) {
					ok = false
					break
				}
			}
			if ok {
				matches = append(matches, match{final: "hmac(" + keyExpr.name + "," + msgExpr.name + ")"})
			}
		}
	}

	for _, direct := range keys {
		ok := true
		for _, sample := range samples {
			if !bytes.Equal(direct.get(sample), sample.headerMAC) {
				ok = false
				break
			}
		}
		if ok {
			matches = append(matches, match{final: direct.name})
		}
	}

	if len(matches) == 0 {
		t.Fatal("no matches")
	}
	for _, m := range matches {
		t.Logf("match: %s", m.final)
	}
}
